    CertificateTemplate = apps.get_model("careers", "CertificateTemplate")
    CertificateDesign = apps.get_model("careers", "CertificateDesign")
    active = CertificateTemplate.objects.filter(is_active=True).first()
    frozen = {}
    issued = TrainingEnrollment.objects.filter(certificate_issued_at__isnull=False, certificate_design__isnull=True)
